// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }

    function testFuzz_property(address ownerEOA, address unrelatedCaller, uint96 dummyBalance) public {
        vm.assume(ownerEOA != address(0));
        vm.assume(unrelatedCaller != address(0));
        vm.assume(ownerEOA != unrelatedCaller);
        vm.assume(ownerEOA != address(c));
        vm.assume(unrelatedCaller != address(c));
        vm.assume(ownerEOA.code.length == 0);
        vm.assume(unrelatedCaller.code.length == 0);

        vm.prank(address(this));
        c.transferOwnership(ownerEOA);

        vm.prank(ownerEOA);
        address ownerReportedByEOA = c.owner();

        vm.prank(unrelatedCaller);
        address ownerReportedByUnrelated = c.owner();

        assertTrue(
            ownerReportedByUnrelated == ownerEOA && ownerReportedByEOA == ownerEOA,
            "owner() must return the stored owner regardless of caller"
        );
    }
}
